      "citations": [
        {
          "index": 0,
          "quote": "WAL works best with smaller transactions."
        }
      ]
    },
    {
      "claim_text": "For transactions larger than about 10 megabytes, the traditional rollback journal modes will likely be faster",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 0 states that traditional rollback journal modes are likely faster for transactions larger than about 100 megabytes, not 10 megabytes. The answer incorrectly changes the threshold value.",
      "citations": [
        {
          "index": 0,
          "quote": "For transactions larger than about 100 megabytes, traditional rollback journal modes will likely be faster."
        }
      ]
    },
    {
      "claim_text": "transactions in excess of a gigabyte may fail with an I/O or disk-full error.",
      "verdict": "SUPPORTED",
      "reasoning": "This claim is directly supported by Passage 0, which states that WAL mode may fail with these errors for transactions exceeding a gigabyte.",
      "citations": [
        {
          "index": 0,
          "quote": "For transactions in excess of a gigabyte, WAL mode may fail with an I/O or disk-full error."
        }
      ]
    },
    {
      "claim_text": "In applications that mostly read, WAL can be roughly 1% or 2% slower than rollback journaling.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states that WAL might be very slightly slower (perhaps 1% or 2%) in applications that do mostly reads and seldom write. This matches the claim.",
      "citations": [
        {
          "index": 1,
          "quote": "WAL might be very slightly slower (perhaps 1% or 2% slower) than the traditional rollback-journal approach in applications that do mostly reads and seldom write."
        }
      ]
    },
    {
      "claim_text": "Write transactions are fast because the content only has to be written once.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 explicitly states that write transactions are very fast because they involve writing the content once (versus twice for rollback-journal).",
      "citations": [
        {
          "index": 2,
          "quote": "Write transactions are very fast since they only involve writing the content once"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "A checkpoint can run concurrently with readers, but it must stop when it reaches a page in the WAL that is past the end mark of any current reader.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states that a checkpoint can run concurrently with readers and must stop when it reaches a page in the WAL past the end mark of any current reader.",
      "citations": [
        {
          "index": 0,
          "quote": "A checkpoint can run concurrently with readers, however the checkpoint must stop when it reaches a page in the WAL that is past the end mark of any current reader."
        }
      ]
    },
    {
      "claim_text": "As a result, a long-running read transaction can prevent the checkpointer from making progress.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] directly states that a long-running read transaction can prevent a checkpointer from making progress.",
      "citations": [
        {
          "index": 1,
          "quote": "Thus a long-running read transaction can prevent a checkpointer from making progress."
        }
      ]
    },
    {
      "claim_text": "If there is always at least one active reader, checkpoints still complete, just more slowly.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [3] states that if there is always at least one active reader, no checkpoints will be able to complete. The claim contradicts this by saying they still complete.",
      "citations": [
        {
          "index": 3,
          "quote": "However, if a database has many concurrent overlapping readers and there is always at least one active reader, then no checkpoints will be able to complete"
        }
      ]
    },
    {
      "claim_text": "Running manual checkpoints with SQLITE_CHECKPOINT_RESTART guarantees that readers are never blocked.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [4] states that the disadvantage of using SQLITE_CHECKPOINT_RESTART is that readers might block while the checkpoint is running. The claim asserts the opposite.",
      "citations": [
        {
          "index": 4,
          "quote": "The disadvantage of using SQLITE_CHECKPOINT_RESTART and SQLITE_CHECKPOINT_TRUNCATE is that readers might block while the checkpoint is running."
        }
      ]
    },
    {
      "claim_text": "Checkpoint starvation is the most common cause of WAL file growth in production systems.",
      "verdict": "UNSUPPORTED",
      "reasoning": "While Passage [2] defines checkpoint starvation and Passage [3] links it to unbounded WAL growth, none of the passages discuss frequency or state that it is the 'most common' cause in production systems.",
      "citations": []
    }
  ]
}

{
